pages.script:
const BUTTONS = {
  btn1: { label: 'Red', name: 'Red', hex: '#ef4444' },
  btn2: { label: 'Amber', name: 'Amber', hex: '#f59e0b' },
  btn3: { label: 'Green', name: 'Green', hex: '#10b981' },
  btn4: { label: 'Blue', name: 'Blue', hex: '#3b82f6' },
  btn5: { label: 'Violet', name: 'Violet', hex: '#8b5cf6' },
  btn6: { label: 'Pink', name: 'Pink', hex: '#ec4899' },
  btn7: { label: 'Indigo', name: 'Indigo', hex: '#6366f1' }
}

function infoFor(name) {
  for (const key in BUTTONS) {
    if (BUTTONS[key].label === name) return BUTTONS[key]
  }
  return { label: name, name: name, hex: '#6366f1' }
}

function showColor(name) {
  const info = infoFor(name)
  store.set('lastColor', info.name)
  controls.swatch.color = info.hex
}

function press(name) {
  store.set('last', name)
  showColor(name)
}

function wire(btn, name) {
  if (!btn) return
  btn.on('click', function () {
    showColor(name)
  })
}

function pageEnter() {
  store.set('last', '')
  store.set('lastColor', '')
  controls.swatch.color = '#1e293b'
  controls.colorText.textColor = '#f8fafc'
  wire(controls.btn1, 'Red')
  wire(controls.btn2, 'Amber')
  wire(controls.btn3, 'Green')
  wire(controls.btn4, 'Blue')
  wire(controls.btn5, 'Violet')
  wire(controls.btn6, 'Pink')
  wire(controls.btn7, 'Indigo')
}

on.click:
const hex = '#' + Math.floor(Math.random() * 0xffffff).toString(16).padStart(6, '0')
const r = parseInt(hex.slice(1, 3), 16)
const g = parseInt(hex.slice(3, 5), 16)
const b = parseInt(hex.slice(5, 7), 16)
const lum = (0.299 * r + 0.587 * g + 0.114 * b) / 255
self.background = hex
self.textColor = lum > 0.6 ? '#0f172a' : '#ffffff'
controls.swatch.color = hex
store.set('lastColor', hex)
store.set('last', 'Random')

pages.script:
function pageEnter() {
  store.set('display', '0')
  store.set('acc', null)
  store.set('op', null)
  store.set('fresh', true)
  installMemWatch()
}

function round(n) {
  return Math.round(n * 1e10) / 1e10
}

function show(n) {
  if (!isFinite(n)) {
    store.set('display', 'Error')
    store.set('acc', null)
    store.set('op', null)
    store.set('fresh', true)
    return
  }
  store.set('display', String(round(n)))
}

function digit(d) {
  const cur = String(store.get('display'))
  if (store.get('fresh') || cur === 'Error') {
    store.set('display', String(d))
    store.set('fresh', false)
    return
  }
  if (cur === '0') store.set('display', String(d))
  else if (cur.replace('-', '').replace('.', '').length < 12) store.set('display', cur + d)
}

function dot() {
  const cur = String(store.get('display'))
  if (store.get('fresh') || cur === 'Error') {
    store.set('display', '0.')
    store.set('fresh', false)
    return
  }
  if (!cur.includes('.')) store.set('display', cur + '.')
}

function compute() {
  const acc = store.get('acc')
  const op = store.get('op')
  const cur = Number(store.get('display'))
  if (op === null || acc === null) return cur
  let r = acc
  if (op === '+') r = acc + cur
  else if (op === '-') r = acc - cur
  else if (op === '*') r = acc * cur
  else if (op === '/') r = cur === 0 ? NaN : acc / cur
  return round(r)
}

function chooseOp(o) {
  const r = compute()
  show(r)
  if (store.get('display') === 'Error') return
  store.set('acc', r)
  store.set('op', o)
  store.set('fresh', true)
}

function equals() {
  const r = compute()
  show(r)
  store.set('acc', null)
  store.set('op', null)
  store.set('fresh', true)
}

function clearAll() {
  store.set('display', '0')
  store.set('acc', null)
  store.set('op', null)
  store.set('fresh', true)
}

function toggleSign() {
  const cur = String(store.get('display'))
  if (cur === 'Error') return
  if (cur.startsWith('-')) store.set('display', cur.slice(1))
  else if (cur !== '0') store.set('display', '-' + cur)
}

function percent() {
  const cur = Number(store.get('display'))
  if (!isFinite(cur)) return
  show(cur / 100)
  store.set('fresh', false)
}

function syncMem() {
  const m = Number(store.get('mem'))
  memDot.visible = isFinite(m) && m !== 0
}

function installMemWatch() {
  syncMem()
  if (store.get('memWatch')) return
  store.set('memWatch', true)
  const rawSet = store.set.bind(store)
  store.set = function (key, value) {
    const r = rawSet(key, value)
    if (key === 'mem') syncMem()
    return r
  }
}

on.click:
const v = Number(store.get('display'))
if (isFinite(v)) {
  const m = Number(store.get('mem')) || 0
  store.set('mem', Math.round((m + v) * 1e10) / 1e10)
  store.set('fresh', true)
}

const v = Number(store.get('display'))
if (isFinite(v)) {
  const m = Number(store.get('mem')) || 0
  store.set('mem', Math.round((m - v) * 1e10) / 1e10)
  store.set('fresh', true)
}
